def minPresses(lamps):
    R, C = len(lamps), len(lamps[0])
    start = 0
    for i in range(R):
        for j in range(C):
            if lamps[i][j]:
                start |= 1 << (i * C + j)
    if start == 0:
        return 0
    masks = []
    for i in range(R):
        for j in range(C):
            m = 1 << (i * C + j)
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < R and 0 <= b < C:
                    m |= 1 << (a * C + b)
            masks.append(m)
    seen = {start}
    frontier = [start]
    steps = 0
    while frontier:
        steps += 1
        nxt = []
        for s in frontier:
            for m in masks:
                t = s ^ m
                if t == 0:
                    return steps
                if t not in seen:
                    seen.add(t)
                    nxt.append(t)
        frontier = nxt
    return -1
